import { useState } from 'react';
import './App.css';

export const PROJECT_NAME = 'atlas-web';

/** Space between a tooltip and its button, and the least space between a tooltip and the page's sides, in px. */
export const TOOLTIP_GAP = 8;

export interface Help {
  /** The info button's accessible name. */
  name: string;
  /** What the tooltip says. */
  text: string;
}

export interface Field {
  label: string;
  value: string;
  help?: Help;
}

export const FIELDS: Field[] = [
  { label: 'Project name', value: PROJECT_NAME },
  {
    label: 'Region',
    value: 'Frankfurt',
    help: {
      name: 'About regions',
      text: 'Builds run and logs are stored in this region. Moving a project to another region pauses its deploys for up to an hour.',
    },
  },
  { label: 'Build cache', value: 'On' },
  {
    label: 'Log retention',
    value: '30 days',
    help: {
      name: 'About log retention',
      text: 'Logs older than this are deleted every night. Logs you exported are kept until you delete them yourself.',
    },
  },
  { label: 'Deploy alerts', value: 'Email' },
  { label: 'Preview deploys', value: 'Every branch' },
];

// TODO Task 1: render `.modal-backdrop`, with `.modal` inside it, into document.body with createPortal, so the
//              backdrop covers the window instead of only the card. Give `.modal` role="dialog", aria-modal="true"
//              and an aria-labelledby set to the id of `.modal-title`. Close it on Cancel, on Escape wherever focus
//              is while it is open, and on a click on `.modal-backdrop` whose press and release both landed on the
//              backdrop; a click inside the dialog, or a drag between the dialog and the backdrop, keeps it open.
//              Focus `.confirm-input` when it opens and `.delete` when it closes, however it closed.
// TODO Task 2: keep focus inside the open dialog. Tab and Shift+Tab move through its enabled controls as usual and
//              wrap at its ends (`.confirm-delete` counts only while it is enabled). The checks press Tab the way a
//              browser does: focus moves on unless a keydown handler cancels the key. While the dialog is open, set
//              `inert` on `.page` and the `modal-open` class on document.body (App.css stops the page scrolling with
//              it); remove both on every close, and the class when App unmounts.
// TODO Task 3: show each `.info` button's tooltip while the button is hovered or focused, so a focused button
//              keeps it when the pointer leaves; Escape hides it wherever focus is, until that button is hovered or
//              focused again. Render it into document.body only while it shows, with role="tooltip" and an id from
//              useId, and point the button's aria-describedby at it only while it shows. Measure it before the
//              browser paints and place it TOOLTIP_GAP below the button, centered and kept TOOLTIP_GAP inside the
//              page's visible width (the left side wins on a narrow page); if it would end past the bottom of
//              `.settings`, place it TOOLTIP_GAP above instead, and set data-placement="bottom" or "top" to match.
//              Place it again when `.settings` scrolls while its button is wholly inside the panel, and hide it
//              once the button is partly scrolled out.

function InfoButton({ help }: { help: Help }) {
  const [shown, setShown] = useState(false);

  return (
    <span className="info-anchor">
      <button
        type="button"
        className="info"
        aria-label={help.name}
        onMouseEnter={() => setShown(true)}
        onMouseLeave={() => setShown(false)}
      >
        i
      </button>
      {shown && <span className="tooltip tooltip-inline">{help.text}</span>}
    </span>
  );
}

export default function App() {
  const [open, setOpen] = useState(false);
  const [confirmText, setConfirmText] = useState('');
  const [status, setStatus] = useState('');

  const closeDialog = () => {
    setOpen(false);
    setConfirmText('');
  };

  const deleteProject = () => {
    closeDialog();
    setStatus(`${PROJECT_NAME} is scheduled for deletion.`);
  };

  return (
    <main className="page">
      <header className="topbar">
        <a className="back" href="#deployments">
          Deployments
        </a>
        <span className="crumb">/ {PROJECT_NAME} / Settings</span>
      </header>
      <section className="card">
        <header className="card-header">
          <h1 className="title">Project settings</h1>
          <p className="subtitle">{PROJECT_NAME} · Production</p>
        </header>

        <div className="settings">
          {FIELDS.map((field) => (
            <div className="field" key={field.label}>
              <span className="field-label">
                {field.label}
                {field.help && <InfoButton help={field.help} />}
              </span>
              <span className="field-value">{field.value}</span>
            </div>
          ))}
        </div>

        <footer className="danger">
          <div className="danger-copy">
            <h2 className="danger-title">Delete project</h2>
            <p className="danger-text">Removes every deployment, environment and log.</p>
          </div>
          <button type="button" className="delete" onClick={() => setOpen(true)}>
            Delete project
          </button>
        </footer>
        <p className="status" role="status">{status}</p>

        {open && (
          <div className="modal-backdrop">
            <div className="modal">
              <h2 className="modal-title">Delete {PROJECT_NAME}?</h2>
              <p className="modal-text">This removes 14 deployments, 3 environments and every log within the hour.</p>
              <label className="confirm-label" htmlFor="confirm-name">
                Type <strong>{PROJECT_NAME}</strong> to confirm
              </label>
              <input
                id="confirm-name"
                className="confirm-input"
                autoComplete="off"
                spellCheck={false}
                value={confirmText}
                onChange={(event) => setConfirmText(event.target.value)}
              />
              <div className="modal-actions">
                <button type="button" className="cancel" onClick={closeDialog}>
                  Cancel
                </button>
                <button
                  type="button"
                  className="confirm-delete"
                  disabled={confirmText !== PROJECT_NAME}
                  onClick={deleteProject}
                >
                  Delete this project
                </button>
              </div>
            </div>
          </div>
        )}
      </section>
    </main>
  );
}

