:root {
  color-scheme: dark;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

/* Set on body while the dialog is open: the page behind it stops scrolling. */

body.modal-open {
  overflow: hidden;
}

.page {
  box-sizing: border-box;
  min-height: 100vh;
  background: #020617;
  color: #e5e7eb;
  display: grid;
  grid-template-columns: minmax(0, 520px);
  justify-content: center;
  align-content: start;
  gap: 20px;
  padding: 24px 16px;
}

.topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  padding: 12px 16px;
  border: 1px solid #1f2937;
  border-radius: 12px;
  background: #0f172a;
  font-size: 14px;
}

.back {
  color: #93c5fd;
  font-weight: 600;
  text-decoration: none;
}

.back:hover {
  text-decoration: underline;
}

.back:focus-visible {
  outline: 2px solid #93c5fd;
  outline-offset: 2px;
}

.crumb {
  color: #9ca3af;
  overflow-wrap: anywhere;
}

/* The card slides in; the animation leaves a transform on it. */

.card {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  background: #0b1220;
  border: 1px solid #1f2937;
  border-radius: 16px;
  display: grid;
  animation: card-rise 240ms ease-out both;
}

@keyframes card-rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .card {
    animation-duration: 1ms;
  }
}

.card-header {
  display: grid;
  gap: 4px;
  padding: 18px 18px 12px;
  border-bottom: 1px solid #1f2937;
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

/* The settings scroll inside a fixed height. The min-width keeps the panel laid out in the 1px-wide frame the
   checks run in. */

.settings {
  height: 288px;
  min-width: 240px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.field {
  box-sizing: border-box;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 18px;
  border-bottom: 1px solid #1f2937;
  font-size: 14px;
}

.field-label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #cbd5e1;
}

.field-value {
  color: #e5e7eb;
  font-weight: 600;
  text-align: right;
}

.info-anchor {
  position: relative;
  display: inline-flex;
}

.info {
  box-sizing: border-box;
  width: 24px;
  height: 24px;
  flex: none;
  display: inline-grid;
  place-items: center;
  padding: 0;
  border: 1px solid #334155;
  border-radius: 999px;
  background: #0f172a;
  color: #93c5fd;
  font: 600 12px/1 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  cursor: help;
}

.info:focus-visible,
.delete:focus-visible,
.cancel:focus-visible,
.confirm-delete:focus-visible {
  outline: 2px solid #93c5fd;
  outline-offset: 2px;
}

.tooltip {
  position: absolute;
  /* Below the dialog's backdrop, so a tooltip left open under the pointer does not cover it. */
  z-index: 5;
  box-sizing: border-box;
  width: 240px;
  padding: 8px 12px;
  border: 1px solid #334155;
  border-radius: 8px;
  background: #111827;
  color: #e5e7eb;
  font-size: 13px;
  line-height: 18px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  pointer-events: none;
}

/* The starter's tooltip: drawn inside the row, where the panel and the card clip it. */

.tooltip-inline {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
}

.danger {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border-top: 1px solid #1f2937;
}

.danger-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.danger-title {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  color: #fca5a5;
}

.danger-text {
  margin: 0;
  font-size: 13px;
  color: #9ca3af;
}

.delete,
.confirm-delete {
  background: #7f1d1d;
  color: #fee2e2;
  border: 1px solid #b91c1c;
  border-radius: 8px;
  padding: 8px 14px;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.confirm-delete:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.status {
  margin: 0;
  min-height: 18px;
  padding: 0 18px 14px;
  font-size: 13px;
  color: #93c5fd;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(2, 6, 23, 0.72);
}

.modal {
  box-sizing: border-box;
  width: 100%;
  max-width: 420px;
  display: grid;
  gap: 12px;
  padding: 20px;
  border: 1px solid #334155;
  border-radius: 14px;
  background: #0f172a;
  color: #e5e7eb;
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.5);
}

.modal-title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.modal-text {
  margin: 0;
  font-size: 14px;
  line-height: 20px;
  color: #cbd5e1;
}

.confirm-label {
  font-size: 13px;
  color: #9ca3af;
}

.confirm-input {
  box-sizing: border-box;
  width: 100%;
  background: #020617;
  color: #e5e7eb;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 8px 10px;
  font: inherit;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.cancel {
  background: #1e293b;
  color: #e5e7eb;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 8px 14px;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}
